import { ResponseError } from "../../errors.js";
import { protocolAPIsById } from "../../protocol/apis.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  ApiVersions Request (Version: 2) =>
*/
export function createRequest(_clientSoftwareName, _clientSoftwareVersion) {
    return Writer.create();
}
/*
  ApiVersions Response (Version: 2) => error_code [api_keys] throttle_time_ms
    error_code => INT16
    api_keys => api_key min_version max_version
      api_key => INT16
      min_version => INT16
      max_version => INT16
    throttle_time_ms => INT32
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const response = {
        errorCode: reader.readInt16(),
        apiKeys: reader.readArray(r => {
            const apiKey = r.readInt16();
            return {
                apiKey,
                name: protocolAPIsById[apiKey],
                minVersion: r.readInt16(),
                maxVersion: r.readInt16()
            };
        }, false, false),
        throttleTimeMs: reader.readInt32()
    };
    if (response.errorCode !== 0) {
        throw new ResponseError(apiKey, apiVersion, { '/': [response.errorCode, null] }, response);
    }
    return response;
}
export const api = createAPI(18, 2, createRequest, parseResponse, false, false);
